{
  "findings": [
    {
      "check_id": "CKV_AWS_149",
      "title": "SSM Document permissions are not restricted",
      "resource": "aws_ssm_document.pass2",
      "severity": "MEDIUM",
      "explanation": "The SSM document is shared with a specific account ID, but it should be verified if this account ID is correct and if it's the only one that needs access."
    },
    {
      "check_id": "CKV_AWS_271",
      "title": "SSM Document content is not validated for potential security risks",
      "resource": "aws_ssm_document.pass2",
      "severity": "LOW",
      "explanation": "The SSM document runs a shell script with the command 'ifconfig', which is not inherently insecure but could potentially be used to gather sensitive network information."
    },
    {
      "check_id": "UNKNOWN",
      "title": "SSM Document account_ids should be a list",
      "resource": "aws_ssm_document.pass2",
      "severity": "HIGH",
      "explanation": "The 'account_ids' attribute in the 'permissions' block is expected to be a list, but it's provided as a string."
    }
  ],
  "patched_code": "resource "aws_ssm_document" "pass2" {
  name          = "test_document"
  document_type = "Command"

  content = <<DOC
  {
    "schemaVersion": "1.2",
    "description": "Check ip configuration of a Linux instance.",
    "parameters": {

    },
    "runtimeConfig": {
      "aws:runShellScript": {
        "properties": [
          {
            "id": "0.aws:runShellScript",
            "runCommand": ["ifconfig"]
          }
        ]
      }
    }
  }
DOC
  permissions = {
    type        = "Share"
    account_ids = ["680235478471"]
  }
}
",
  "fix_summary": "Changed 'account_ids' to be a list by adding square brackets around the account ID."
}
